/* AUTO-GENERATED by scripts/gen-iot-examples.mjs — do not edit.
   Source of truth: iot-examples.manifest.json → the real composition files under apps/web/src/examples/iot/ */
export const iotExampleSource: Record<string, string> = {
  "state-honesty": "/**\n * Requested is not confirmed.\n *\n * Press a control and watch two values that most device UIs collapse into one: what you ASKED for, and\n * what the device last REPORTED. The confirmed value changes only when the device confirms it. An\n * acknowledgement (\"I got that\") is not a confirmation, a timeout is not \"off\", and a device that\n * stopped answering is `unreachable` rather than quietly assumed to have obeyed.\n *\n * Everything here is scripted in the browser. `@kinetixui/iot` has no transport, so no request leaves\n * the page, and no delay below is a real network delay.\n */\nfunction Panel({ title, note, binding, children }: { title: string; note: string; binding: ControlBinding; children: React.ReactNode }) {\n  const { command, confirmed, requested, format } = binding;\n  return (\n    <article className=\"flex min-w-0 flex-col gap-3 rounded-2xl border border-border bg-card p-4\">\n      <header>\n        <h4 className=\"text-title-sm text-foreground\">{binding.device.name}</h4>\n        <p className=\"text-label-sm text-muted-foreground\">\n          {title}. {note}\n        </p>\n      </header>\n      {children}\n      <dl className=\"grid grid-cols-2 gap-3 rounded-lg border border-border bg-muted/30 p-3 text-label-md\">\n        <div className=\"min-w-0\">\n          <dt className=\"text-label-sm text-muted-foreground\">Device reports (confirmed)</dt>\n          <dd data-testid={`confirmed-${binding.device.id}`} className=\"font-medium text-foreground\">\n            {format(confirmed)}\n          </dd>\n        </div>\n        <div className=\"min-w-0\">\n          <dt className=\"text-label-sm text-muted-foreground\">You asked for (requested)</dt>\n          <dd data-testid={`requested-${binding.device.id}`} className=\"font-medium text-foreground\">\n            {requested === undefined ? \"Nothing pending\" : format(requested)}\n          </dd>\n        </div>\n      </dl>\n      {command ? <CommandLifecycle lifecycle={command.lifecycle} formatValue={format} onRetry={binding.retry} onCancel={binding.cancel} /> : null}\n    </article>\n  );\n}\n\nexport function StateHonestyExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 500 });\n  const valve02 = controlOf(iot, \"valve-02\", \"position\");\n  const valve03 = controlOf(iot, \"valve-03\", \"position\");\n  const pump = controlOf(iot, \"pump-01\", \"power\");\n  const pumpGone = !iot.sim.devices[\"pump-01\"]!.reachable;\n  const pumpBusy = pump.command ? isLifecyclePending(pump.command.lifecycle) : false;\n\n  return (\n    <section aria-label=\"State honesty demo\" className=\"flex flex-col gap-5\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,18rem),1fr))] gap-4\">\n        {([[\"Reliable valve\", \"Acknowledges, then confirms.\", valve02], [\"Flaky valve\", \"Fails once, then works. Retry is offered, never done for you.\", valve03]] as const).map(\n          ([title, note, valve]) => (\n            <Panel key={valve.device.id} title={title} note={note} binding={valve}>\n              <DeviceModeControl\n                modes={valve.capability.modes ?? []}\n                value={valve.confirmed as string}\n                requested={valve.requested as string | undefined}\n                control={valve.control}\n                label={`${valve.device.name} position`}\n                onSelect={valve.send}\n              />\n            </Panel>\n          ),\n        )}\n\n        <Panel title=\"Unreachable device\" note=\"Send a request, then lose the pump: it times out, then is called unreachable.\" binding={pump}>\n          <DevicePowerControl\n            state={pump.confirmed as \"on\" | \"off\"}\n            requested={pump.requested as \"on\" | \"off\" | undefined}\n            control={pump.control}\n            label={`${pump.device.name} power`}\n            onToggle={pump.send}\n          />\n          <div className=\"flex flex-wrap gap-2\">\n            <button\n              type=\"button\"\n              className={BUTTON}\n              disabled={pumpGone || pumpBusy}\n              onClick={() => {\n                pump.send(pump.confirmed === \"on\" ? \"off\" : \"on\");\n                iot.setReachable(\"pump-01\", false);\n              }}\n            >\n              Request a change, then lose the pump\n            </button>\n            <button type=\"button\" className={BUTTON} disabled={!pumpGone} onClick={() => iot.setReachable(\"pump-01\", true)}>\n              Pump answers again\n            </button>\n          </div>\n        </Panel>\n      </div>\n\n      <p className=\"text-label-sm text-muted-foreground\">\n        An optimistic interface would already show the new value the moment you pressed. Here the confirmed value never moves until the device\n        confirms it, so a lock, a valve or a pump is never shown in a state it has not reported.\n      </p>\n    </section>\n  );\n}",
  "smart-space-environment": "/**\n * A smart space, end to end: rooms with health rolled up from their devices, real controls that show\n * requested against confirmed, air quality, a camera that is never shown as live, energy, alerts and\n * scenes. Built from one simulated scenario through selectors, so nothing here is a hand-typed count.\n *\n * SIMULATED. No device is contacted and nothing is sent over a network.\n */\nconst DAY_MS = 86_400_000;\n\n/** The lifecycle of a request that has not landed, or did not. Nothing for a confirmed one. */\nfunction Lifecycle({ binding }: { binding: ControlBinding }) {\n  if (!binding.command || !binding.unsettled) return null;\n  return <CommandLifecycle lifecycle={binding.command.lifecycle} formatValue={binding.format} onRetry={binding.retry} onCancel={binding.cancel} className=\"w-full\" />;\n}\n\nexport function SmartSpaceEnvironmentExample() {\n  const iot = useIotSimulation(smartSpace, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [spaceId, setSpaceId] = React.useState(\"home\");\n  const [openIds, setOpenIds] = React.useState<Record<string, boolean>>({ \"thermostat-hall\": true });\n  const disclose = (id: string) => ({ open: !!openIds[id], onOpenChange: (open: boolean) => setOpenIds((prev) => ({ ...prev, [id]: open })) });\n  const [enabled, setEnabled] = React.useState<Record<string, boolean>>({});\n\n  const tree = React.useMemo(() => buildSpaceTree(sim.scenario.spaces), [sim.scenario.spaces]);\n  const rollups = selectSpaceRollups(sim);\n  const rooms = sim.scenario.spaces.filter((space) => space.kind === \"room\");\n  const shownIds = new Set(descendantDeviceIds(tree, spaceId));\n  const show = (deviceId: string) => shownIds.has(deviceId);\n  const lamp = controlOf(iot, \"lamp-living\", \"power\");\n  const brightness = controlOf(iot, \"lamp-living\", \"level\");\n  const thermostat = controlOf(iot, \"thermostat-hall\", \"setpoint\");\n  const thermostatMode = controlOf(iot, \"thermostat-hall\", \"mode\");\n  const heater = controlOf(iot, \"plug-heater\", \"power\");\n  const lock = controlOf(iot, \"lock-front\", \"lock\");\n  const bedroom = controlOf(iot, \"lamp-bedroom\", \"power\");\n  const energy = selectEnergy(sim);\n  const dayLabels = energy?.week.map((_, i) =>\n    new Date(Date.parse(sim.startAt) - (energy.week.length - i) * DAY_MS).toLocaleDateString(\"en\", { weekday: \"short\", timeZone: \"UTC\" }),\n  );\n\n  return (\n    <section aria-label=\"Smart space\" className=\"flex flex-col gap-6\">\n      <SimNotice scenario={smartSpace}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <Section title=\"Rooms\" hint=\"Health is rolled up from the devices in each room. Select one to filter the controls below.\">\n        <SpaceBreadcrumb path={spacePath(tree, spaceId)} label=\"Selected space\" onNavigate={(item) => setSpaceId(item.id)} />\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {rooms.map((room) => {\n            const ids = descendantDeviceIds(tree, room.id);\n            const rollup = rollups.get(room.id)!;\n            const devices = ids.map((id) => deviceOf(sim, id));\n            return (\n              <DeviceGroupCard\n                key={room.id}\n                name={room.name}\n                kind=\"Room\"\n                deviceCount={devices.length}\n                activeCount={devices.filter((d) => d.status === \"online\").length}\n                attentionCount={rollup.warning + rollup.critical + rollup.offline}\n                category={devices[0] ? resolveDeviceCategory(devices[0]) : undefined}\n                path={<SpaceBreadcrumb path={spacePath(tree, room.id)} label={`Location of ${room.name}`} />}\n                rollup={<SpaceRollup rollup={rollup} name={room.name} compact />}\n                onSelect={() => setSpaceId(room.id)}\n                aria-current={spaceId === room.id ? \"true\" : undefined}\n                className={spaceId === room.id ? \"ring-2 ring-ring ring-offset-2 ring-offset-background\" : undefined}\n              />\n            );\n          })}\n        </div>\n        {spaceId !== \"home\" ? (\n          <button type=\"button\" className={`${BUTTON} self-start`} onClick={() => setSpaceId(\"home\")}>\n            Show the whole home\n          </button>\n        ) : null}\n      </Section>\n\n      <Section title=\"Controls\" hint=\"Each control shows what the device reported. A request stays visibly unconfirmed until the device agrees.\">\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,18rem),1fr))] gap-3\">\n          {show(\"lamp-living\") ? (\n            <DeviceControlCard\n              device={lamp.device}\n              active={lamp.confirmed === \"on\"}\n              control={lamp.control}\n              statusLine={statusLineOf(lamp, brightness)}\n              primaryControl={\n                <DevicePowerControl state={lamp.confirmed as \"on\" | \"off\"} requested={lamp.requested as \"on\" | \"off\" | undefined} control={lamp.control} label=\"Living room lamp power\" showLabel={false} onToggle={lamp.send} />\n              }\n              meta={<Lifecycle binding={lamp} />}\n              expanded={\n                <>\n                  <DeviceLevelControl value={brightness.confirmed as number} target={brightness.requested as number | undefined} unit=\"%\" step={5} control={brightness.control} label=\"Living room lamp brightness\" onCommit={brightness.send} />\n                  <Lifecycle binding={brightness} />\n                </>\n              }\n              {...disclose(\"lamp-living\")}\n            />\n          ) : null}\n\n          {show(\"thermostat-hall\") ? (\n            <DeviceControlCard\n              device={thermostat.device}\n              active={thermostatMode.confirmed === \"heat\"}\n              control={thermostat.control}\n              statusLine={statusLineOf(thermostat, thermostatMode)}\n              meta={<Lifecycle binding={thermostat} />}\n              expanded={\n                <>\n                  <DeviceSetpointControl\n                    current={readingOf(iot, \"thermostat-hall\", \"temperature\").value}\n                    target={thermostat.confirmed as number}\n                    requestedTarget={thermostat.requested as number | undefined}\n                    min={16}\n                    max={26}\n                    step={0.5}\n                    unit=\"°C\"\n                    control={thermostat.control}\n                    label=\"Hallway thermostat target\"\n                    onCommit={thermostat.send}\n                  />\n                  <DeviceModeControl modes={thermostatMode.capability.modes ?? []} value={thermostatMode.confirmed as string} requested={thermostatMode.requested as string | undefined} control={thermostatMode.control} label=\"Hallway thermostat mode\" onSelect={thermostatMode.send} />\n                  <Lifecycle binding={thermostatMode} />\n                </>\n              }\n              {...disclose(\"thermostat-hall\")}\n            />\n          ) : null}\n\n          {show(\"plug-heater\") ? (\n            <DeviceControlCard\n              device={heater.device}\n              active={heater.confirmed === \"on\"}\n              control={heater.control}\n              statusLine={statusLineOf(heater)}\n              primaryControl={\n                <DevicePowerControl state={heater.confirmed as \"on\" | \"off\"} requested={heater.requested as \"on\" | \"off\" | undefined} control={heater.control} label=\"Space heater plug power\" showLabel={false} onToggle={heater.send} />\n              }\n              meta={<Lifecycle binding={heater} />}\n            />\n          ) : null}\n\n          {show(\"lock-front\") ? (\n            <DeviceControlCard\n              device={lock.device}\n              control={lock.control}\n              statusLine={statusLineOf(lock)}\n              meta={\n                <>\n                  <DeviceModeControl modes={lock.capability.modes ?? []} value={lock.confirmed as string} requested={lock.requested as string | undefined} control={lock.control} label=\"Front door lock\" onSelect={lock.send} className=\"w-full\" />\n                  <Lifecycle binding={lock} />\n                </>\n              }\n            />\n          ) : null}\n\n          {show(\"lamp-bedroom\") ? (\n            <DeviceControlCard\n              device={bedroom.device}\n              control={bedroom.control}\n              statusLine={statusLineOf(bedroom)}\n              primaryControl={\n                <DevicePowerControl state={bedroom.confirmed as \"on\" | \"off\"} control={bedroom.control} label=\"Bedroom lamp power\" showLabel={false} onToggle={bedroom.send} />\n              }\n            />\n          ) : null}\n        </div>\n      </Section>\n\n      <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,20rem),1fr))] gap-6\">\n        <Section title=\"Air quality · Living room\">\n          <TelemetryGrid label=\"Living room air\">\n            <TelemetryMetric {...readingOf(iot, \"air-living\", \"air-quality\")} label=\"Air quality\" />\n            <TelemetryMetric {...readingOf(iot, \"air-living\", \"temperature\")} label=\"Temperature\" />\n            <TelemetryMetric {...readingOf(iot, \"air-living\", \"humidity\")} label=\"Humidity\" />\n          </TelemetryGrid>\n        </Section>\n\n        <Section title=\"Camera\" hint=\"A sample frame. No video, stream or recording exists behind this card.\">\n          <CameraDeviceCard device={deviceOf(sim, \"camera-hall\")} posterLabel={SAMPLE_IMAGE_LABEL} privacy=\"off\" now={sim.now} />\n        </Section>\n      </div>\n\n      {energy ? (\n        <Section title=\"Energy\" hint=\"Simulated consumption. Devices that are confirmed on accrue as the clock runs.\">\n          <EnergySummary summary={energy.summary} today={energy.summary.total} days={energy.week} dayLabels={dayLabels} />\n        </Section>\n      ) : null}\n\n      <Section title=\"Alerts\">\n        <AlertList\n          alerts={selectAlerts(sim, { includeAcknowledged: true })}\n          deviceName={(id) => deviceOf(sim, id).name}\n          onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n          now={sim.now}\n        />\n      </Section>\n\n      <Section title=\"Scenes and routines\" hint=\"Shown, not executed: KinetixUI has no automation engine.\">\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {sim.automations.map((automation) => {\n            const on = enabled[automation.id] ?? automation.enabled;\n            return (\n              <RoutineCard\n                key={automation.id}\n                automation={{ ...automation, enabled: on, status: on ? (automation.status === \"disabled\" ? \"idle\" : automation.status) : \"disabled\" }}\n                now={sim.now}\n                onToggleEnabled={(next) => setEnabled((prev) => ({ ...prev, [automation.id]: next }))}\n              />\n            );\n          })}\n        </div>\n      </Section>\n    </section>\n  );\n}",
  "agritech-environment": "/**\n * Greenhouse A: climate, soil, a valve, a pump and a weather station, on one screen.\n *\n * The valve and pump are real controls: a request stays unconfirmed until the device reports. Irrigation\n * Valve 03 is deliberately flaky. It fails once, shows why, and offers Retry rather than retrying for\n * you. Soil moisture dips through its 28% threshold a few seconds after the page loads.\n *\n * SIMULATED. The rain forecast is application-provided demo data: KinetixUI fetches no forecast.\n */\nexport function AgritechEnvironmentExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 1000 });\n  const { sim } = iot;\n  const tree = React.useMemo(() => buildSpaceTree(sim.scenario.spaces), [sim.scenario.spaces]);\n  const rollups = selectSpaceRollups(sim);\n  const zones = sim.scenario.spaces.filter((space) => space.kind === \"irrigation-zone\" || space.id === \"field-orchard\");\n  const rule = sim.scenario.rules[0]!;\n  const forecast = agritechRainForecast;\n  const valves = [controlOf(iot, \"valve-02\", \"position\"), controlOf(iot, \"valve-03\", \"position\")];\n  const pump = controlOf(iot, \"pump-01\", \"power\");\n\n  return (\n    <section aria-label=\"Greenhouse A\" className=\"flex flex-col gap-6\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <Section title=\"Greenhouse A\">\n        <DeviceHealthSummary summary={selectFleetHealth(sim)} noun={{ one: \"device\", other: \"devices\" }} />\n        <TelemetryGrid label=\"Greenhouse A readings\">\n          <TelemetryMetric {...readingOf(iot, \"climate-a\", \"temperature\")} label=\"Air temperature\" />\n          <TelemetryMetric {...readingOf(iot, \"climate-a\", \"humidity\")} label=\"Humidity\" />\n          <TelemetryMetric {...readingOf(iot, \"soil-04\", \"soil-moisture\")} label=\"Soil moisture · Zone 3\" />\n          <TelemetryMetric {...readingOf(iot, \"pump-01\", \"flow\")} label=\"Pump flow\" />\n          <TelemetryMetric {...readingOf(iot, \"weather-01\", \"wind-speed\")} label=\"Wind\" />\n          <TelemetryMetric {...readingOf(iot, \"soil-05\", \"soil-moisture\")} label=\"Soil moisture · Orchard\" />\n        </TelemetryGrid>\n      </Section>\n\n      <Section title=\"Soil moisture · Zone 3\" hint=\"Seven days. The band below 28% is the threshold the irrigation rule watches.\">\n        <TelemetryTrend {...trendOf(iot, \"soil-04\", \"soil-moisture\")} label=\"Soil moisture, Zone 3, last seven days\" height={140} dataTable />\n      </Section>\n\n      <Section title=\"Valves and pump\" hint=\"Open, closed, running: each shows the reported state and any request still waiting on the device.\">\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,18rem),1fr))] gap-3\">\n          {valves.map((valve) => (\n            <DeviceControlCard\n              key={valve.device.id}\n              device={valve.device}\n              active={valve.confirmed === \"open\"}\n              control={valve.control}\n              statusLine={statusLineOf(valve)}\n              meta={\n                <>\n                  <DeviceModeControl\n                    modes={valve.capability.modes ?? []}\n                    value={valve.confirmed as string}\n                    requested={valve.requested as string | undefined}\n                    control={valve.control}\n                    label={`${valve.device.name} position`}\n                    onSelect={valve.send}\n                    className=\"w-full\"\n                  />\n                  {valve.command && valve.unsettled ? <CommandLifecycle lifecycle={valve.command.lifecycle} formatValue={valve.format} onRetry={valve.retry} onCancel={valve.cancel} className=\"w-full\" /> : null}\n                </>\n              }\n            />\n          ))}\n          <DeviceControlCard\n            device={pump.device}\n            active={pump.confirmed === \"on\"}\n            control={pump.control}\n            statusLine={statusLineOf(pump)}\n            primaryControl={\n              <DevicePowerControl state={pump.confirmed as \"on\" | \"off\"} requested={pump.requested as \"on\" | \"off\" | undefined} control={pump.control} label=\"Pump Station power\" showLabel={false} onToggle={pump.send} />\n            }\n            meta={pump.command && pump.unsettled ? <CommandLifecycle lifecycle={pump.command.lifecycle} formatValue={pump.format} onRetry={pump.retry} onCancel={pump.cancel} className=\"w-full\" /> : null}\n          />\n        </div>\n      </Section>\n\n      <Section title=\"Zones\">\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {zones.map((zone) => {\n            const devices = descendantDeviceIds(tree, zone.id).map((id) => deviceOf(sim, id));\n            const rollup = rollups.get(zone.id)!;\n            return (\n              <DeviceGroupCard\n                key={zone.id}\n                name={zone.name}\n                kind={zone.kind === \"irrigation-zone\" ? \"Irrigation zone\" : \"Field\"}\n                deviceCount={devices.length}\n                activeCount={devices.filter((d) => d.status === \"online\").length}\n                attentionCount={rollup.warning + rollup.critical + rollup.offline}\n                category={devices[0] ? resolveDeviceCategory(devices[0]) : undefined}\n                rollup={<SpaceRollup rollup={rollup} name={zone.name} compact />}\n              />\n            );\n          })}\n        </div>\n      </Section>\n\n      <Section title=\"Alerts\">\n        <AlertList\n          alerts={selectAlerts(sim, { includeAcknowledged: true })}\n          deviceName={(id) => deviceOf(sim, id).name}\n          onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n          now={sim.now}\n        />\n      </Section>\n\n      <Section title=\"Automation\" hint=\"A rule as data. Nothing evaluates it: KinetixUI has no automation engine.\">\n        <AutomationRuleView rule={rule} labelFor={(_kind, id) => sim.scenario.labels?.[id]} />\n        <p className=\"text-label-md text-foreground\">\n          Rain forecast: {forecast.expected ? \"expected\" : \"not expected\"} ({forecast.probabilityPct}% chance)\n        </p>\n        <p className=\"text-label-sm text-muted-foreground\">Application-provided demo data — KinetixUI fetches no forecast.</p>\n      </Section>\n\n      <Section title=\"Recent activity\">\n        <ActivityTimeline events={selectActivity(sim, { limit: 6 })} deviceName={(id) => deviceOf(sim, id).name} now={sim.now} />\n      </Section>\n    </section>\n  );\n}",
  "operations-environment": "/**\n * Site 04: fleet health, an Organization → Site → Line → Machine hierarchy with a rollup at every\n * level, equipment health, energy, faults and alerts, and the command history.\n *\n * Counts come from `summarizeFleetHealth` and `rollupSpaceHealth` over the simulated devices, not from\n * numbers typed into the page. SIMULATED: no device is contacted and nothing is sent over a network.\n */\nexport function OperationsEnvironmentExample() {\n  const iot = useIotSimulation(operations, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [spaceId, setSpaceId] = React.useState(\"site-04\");\n\n  const tree = React.useMemo(() => buildSpaceTree(sim.scenario.spaces), [sim.scenario.spaces]);\n  const rollups = selectSpaceRollups(sim);\n  const here = findSpace(tree, spaceId)!;\n  const energy = selectEnergy(sim);\n  const pump = controlOf(iot, \"p-201\", \"power\");\n  const duty = controlOf(iot, \"p-201\", \"duty\");\n  const commandHistory = selectActivity(sim).filter((event) => event.kind === \"command\");\n\n  return (\n    <section aria-label=\"Site 04 operations\" className=\"flex flex-col gap-6\">\n      <SimNotice scenario={operations}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <Section title=\"Site 04 health\">\n        <DeviceHealthSummary summary={selectFleetHealth(sim)} noun={{ one: \"device\", other: \"devices\" }} />\n      </Section>\n\n      <Section title=\"Where it is\" hint=\"Organization, site, line, machine. Each level rolls up the health of everything beneath it.\">\n        <SpaceBreadcrumb path={spacePath(tree, spaceId)} label=\"Selected level\" onNavigate={(item) => setSpaceId(item.id)} />\n        <SpaceRollup rollup={rollups.get(spaceId)!} name={here.node.name} />\n        {here.children.length > 0 ? (\n          <ul aria-label={`Inside ${here.node.name}`} className=\"m-0 grid list-none grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-3 p-0\">\n            {here.children.map((child) => (\n              <li key={child.node.id} className=\"flex min-w-0 flex-col gap-2 rounded-xl border border-border bg-card p-3\">\n                <div className=\"flex min-w-0 flex-col\">\n                  <span className=\"text-label-sm uppercase tracking-wide text-muted-foreground\">{child.node.kind}</span>\n                  {child.children.length > 0 ? (\n                    <button type=\"button\" className={`${BUTTON} justify-start text-start`} onClick={() => setSpaceId(child.node.id)}>\n                      <span className=\"min-w-0 truncate\">{child.node.name}</span>\n                    </button>\n                  ) : (\n                    <span className=\"truncate text-label-md text-foreground\">{child.node.name}</span>\n                  )}\n                </div>\n                <SpaceRollup rollup={rollups.get(child.node.id)!} name={child.node.name} compact />\n              </li>\n            ))}\n          </ul>\n        ) : null}\n      </Section>\n\n      <Section title=\"Equipment health · Transfer pump P-201\" hint=\"Vibration has climbed for a week. The bands are product-set bounds, not library defaults.\">\n        <TelemetryGrid label=\"Transfer pump P-201 readings\">\n          <TelemetryMetric {...readingOf(iot, \"p-201\", \"pressure\")} label=\"Discharge pressure\" />\n          <TelemetryMetric {...readingOf(iot, \"p-201\", \"vibration\")} label=\"Vibration\" />\n          <TelemetryMetric {...readingOf(iot, \"p-201\", \"temperature\")} label=\"Casing temperature\" />\n        </TelemetryGrid>\n        <TelemetryTrend {...trendOf(iot, \"p-201\", \"vibration\")} label=\"Transfer pump P-201 vibration, last seven days\" height={140} dataTable />\n        <div className=\"max-w-sm\">\n          <DeviceControlCard\n            device={pump.device}\n            active={pump.confirmed === \"on\"}\n            control={pump.control}\n            statusLine={statusLineOf(pump, duty)}\n            primaryControl={\n              <DevicePowerControl state={pump.confirmed as \"on\" | \"off\"} requested={pump.requested as \"on\" | \"off\" | undefined} control={pump.control} label=\"Transfer pump P-201 run\" showLabel={false} onToggle={pump.send} />\n            }\n            meta={\n              <>\n                {pump.command && pump.unsettled ? <CommandLifecycle lifecycle={pump.command.lifecycle} formatValue={pump.format} onRetry={pump.retry} onCancel={pump.cancel} className=\"w-full\" /> : null}\n                {duty.command && duty.unsettled ? <CommandLifecycle lifecycle={duty.command.lifecycle} formatValue={duty.format} onRetry={duty.retry} onCancel={duty.cancel} className=\"w-full\" /> : null}\n              </>\n            }\n            expanded={<DeviceLevelControl value={duty.confirmed as number} target={duty.requested as number | undefined} unit=\"%\" step={5} control={duty.control} label=\"Transfer pump P-201 duty\" onCommit={duty.send} />}\n          />\n        </div>\n      </Section>\n\n      {energy ? (\n        <Section title=\"Energy\" hint=\"Simulated. Confirmed-on machines accrue as the clock runs.\">\n          <EnergySummary summary={energy.summary} today={energy.summary.total} days={energy.week} />\n        </Section>\n      ) : null}\n\n      <Section title=\"Faults and alerts\">\n        <AlertList\n          alerts={selectAlerts(sim, { includeAcknowledged: true })}\n          deviceName={(id) => deviceOf(sim, id).name}\n          onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n          now={sim.now}\n        />\n      </Section>\n\n      <Section title=\"Command history\" hint=\"Requests you send above appear here with the status the device actually reached.\">\n        <ActivityTimeline events={commandHistory} deviceName={(id) => deviceOf(sim, id).name} now={sim.now} label=\"Command history\" />\n      </Section>\n    </section>\n  );\n}",
  "device-detail": "/**\n * One device in full, as a screen with six tabs. The tabs are real `tablist` / `tab` / `tabpanel`\n * elements with roving arrow-key focus (Radix Tabs); on a narrow screen the tabs wrap onto further rows\n * instead of scrolling sideways, where the tabs past the edge would have no visible cue.\n *\n * \"Settings\" is a read-only presentation of what the product knows about the device. Nothing on that\n * tab configures hardware, and nothing in this example sends anything: it is SIMULATED.\n */\nconst DEVICE_ID = \"pump-01\";\nconst TABS = [\"Overview\", \"Controls\", \"Telemetry\", \"Automations\", \"Activity\", \"Settings\"] as const;\n\nconst TAB_TRIGGER = cn(\n  \"inline-flex min-h-11 items-center whitespace-nowrap border-b-2 border-border px-4 text-label-md text-muted-foreground\",\n  \"transition-colors hover:text-foreground motion-reduce:transition-none\",\n  \"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring\",\n  \"data-[state=active]:border-primary data-[state=active]:text-foreground\",\n);\nconst PANEL = \"flex flex-col gap-6 pt-5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\";\n\nexport function DeviceDetailExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [tab, setTab] = React.useState<(typeof TABS)[number]>(\"Overview\");\n  const [rootRef, dir] = useInheritedDirection<HTMLDivElement>();\n\n  const device = deviceOf(sim, DEVICE_ID);\n  const state = selectDeviceState(sim, DEVICE_ID)!;\n  const power = controlOf(iot, DEVICE_ID, \"power\");\n  const powerControl = (\n    <DevicePowerControl state={power.confirmed as \"on\" | \"off\"} requested={power.requested as \"on\" | \"off\" | undefined} control={power.control} label={`${device.name} power`} onToggle={power.send} />\n  );\n  const lifecycle = power.command ? (\n    <CommandLifecycle lifecycle={power.command.lifecycle} formatValue={power.format} onRetry={power.retry} onCancel={power.cancel} />\n  ) : null;\n  const running = state.confirmedValues.power === \"on\";\n  const alerts = state.alerts.filter((alert) => !alert.resolvedAt);\n  const routines = sim.automations.filter((automation) => automation.actions?.toLowerCase().includes(\"pump\"));\n  const rules = sim.scenario.rules.filter((rule) => rule.actions.some((action) => action.target === DEVICE_ID));\n\n  return (\n    <article ref={rootRef} aria-label={`${device.name} detail`} className=\"flex flex-col gap-4\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <header className=\"flex flex-col gap-3 rounded-2xl border border-border bg-card p-4\">\n        <DeviceIdentity device={device} active={running && device.status === \"online\"} size=\"lg\" />\n        <p className=\"flex flex-wrap items-center gap-x-3 gap-y-1 text-label-md text-foreground\">\n          {/* The word \"Running\" is the CONFIRMED state. A request in flight is never shown here. */}\n          <span>{running ? \"Running\" : \"Stopped\"}</span>\n          <DeviceStatusBadge status={device.status} />\n          <span className=\"text-muted-foreground\">\n            {/* LastSync's own accessible label is the whole sentence (\"Last seen 4 seconds ago\"); the\n                visible prefix is hidden from assistive technology so it is not read twice. */}\n            <span aria-hidden=\"true\">Last seen </span>\n            <LastSync value={device.lastSeenAt} now={sim.now} />\n          </span>\n        </p>\n      </header>\n\n      <Tabs.Root value={tab} onValueChange={(next) => setTab(next as (typeof TABS)[number])} dir={dir}>\n        {/* The tabs wrap; each carries its own underline, so the active one still reads on any row. */}\n        <Tabs.List aria-label={`${device.name} sections`} className=\"flex flex-wrap\">\n          {TABS.map((name) => (\n            <Tabs.Trigger key={name} value={name} className={TAB_TRIGGER}>\n              {name}\n            </Tabs.Trigger>\n          ))}\n        </Tabs.List>\n\n        <Tabs.Content value=\"Overview\" className={PANEL}>\n          <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,18rem),1fr))] gap-6\">\n            <Section title=\"Health\">\n              <p className=\"text-label-md text-foreground\">\n                {describeDeviceHealth(state.health.level)} · {describeConnectivity(state.connectivity.state)}\n              </p>\n              <ul className=\"m-0 list-disc ps-5 text-label-md text-muted-foreground\">\n                {state.health.reasons.length === 0 ? <li>No issues reported.</li> : state.health.reasons.map((reason, i) => <li key={i}>{reason.message}</li>)}\n              </ul>\n            </Section>\n            <Section title=\"Connectivity\">\n              <ConnectionHealth device={device} now={sim.now} />\n            </Section>\n          </div>\n          <Section title=\"Primary readings\">\n            <TelemetryGrid label={`${device.name} readings`}>\n              <TelemetryMetric {...readingOf(iot, DEVICE_ID, \"flow\")} label=\"Flow\" />\n              <TelemetryMetric {...readingOf(iot, DEVICE_ID, \"pressure\")} label=\"Pressure\" />\n            </TelemetryGrid>\n          </Section>\n          <Section title=\"Alerts\">\n            <AlertList alerts={alerts} deviceName={() => undefined} onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)} now={sim.now} emptyLabel=\"No open alerts.\" hideSummary />\n          </Section>\n          <Section title=\"Quick controls\">\n            <div className=\"flex flex-wrap items-start gap-3\">{powerControl}</div>\n            {power.unsettled ? lifecycle : null}\n          </Section>\n        </Tabs.Content>\n\n        <Tabs.Content value=\"Controls\" className={PANEL}>\n          <Section title=\"Controls\" hint=\"The switch shows what the pump reported. A request stays visibly unconfirmed until the pump agrees.\">\n            <div className=\"max-w-sm\">\n              <DeviceControlCard device={device} active={running} control={power.control} statusLine={statusLineOf(power)} primaryControl={powerControl} />\n            </div>\n            {lifecycle}\n          </Section>\n        </Tabs.Content>\n\n        <Tabs.Content value=\"Telemetry\" className={PANEL}>\n          <Section title=\"Flow\" hint=\"The band below 20 L/min is the low-flow threshold. Gaps are drawn as gaps.\">\n            <TelemetryTrend {...trendOf(iot, DEVICE_ID, \"flow\")} label=\"Pump flow, last 24 hours\" height={140} dataTable />\n          </Section>\n          <Section title=\"Pressure\">\n            <TelemetryTrend {...trendOf(iot, DEVICE_ID, \"pressure\")} label=\"Pump pressure, last 24 hours\" height={120} dataTable />\n          </Section>\n        </Tabs.Content>\n\n        <Tabs.Content value=\"Automations\" className={PANEL}>\n          <Section title=\"Routines that involve this pump\" hint=\"Shown, not executed: KinetixUI has no automation engine.\">\n            <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n              {routines.map((automation) => (\n                <RoutineCard key={automation.id} automation={automation} now={sim.now} />\n              ))}\n            </div>\n          </Section>\n          {rules.length > 0 ? (\n            rules.map((rule) => <AutomationRuleView key={rule.id} rule={rule} />)\n          ) : (\n            <p className=\"text-label-sm text-muted-foreground\">No structured rule in this scenario targets the pump directly.</p>\n          )}\n        </Tabs.Content>\n\n        <Tabs.Content value=\"Activity\" className={PANEL}>\n          <Section title=\"Commands and state changes\">\n            <ActivityTimeline events={selectActivity(sim, { deviceId: DEVICE_ID })} deviceName={() => undefined} now={sim.now} label={`${device.name} activity`} />\n          </Section>\n        </Tabs.Content>\n\n        <Tabs.Content value=\"Settings\" className={PANEL}>\n          <Section title=\"About this device\" hint=\"Read-only. Nothing on this tab configures hardware; it presents what the product knows.\">\n            <dl className=\"m-0 grid grid-cols-[repeat(auto-fit,minmax(min(100%,14rem),1fr))] gap-x-6 gap-y-3 text-label-md\">\n              {(\n                [\n                  [\"Device id\", device.id],\n                  [\"Type\", device.type],\n                  [\"Firmware\", device.firmwareVersion ?? \"Not reported\"],\n                  [\"Site\", device.site ?? \"Not set\"],\n                  [\"Zone\", device.zone ?? \"Not set\"],\n                  [\"Location\", device.locationName ?? \"Not set\"],\n                  [\"Signal\", device.signal === undefined ? \"Not reported\" : `${device.signal}%`],\n                  [\"Battery\", device.battery === undefined ? \"Not reported\" : `${device.battery}%`],\n                ] as const\n              ).map(([term, value]) => (\n                <div key={term} className=\"min-w-0\">\n                  <dt className=\"text-label-sm text-muted-foreground\">{term}</dt>\n                  <dd className=\"m-0 break-words text-foreground\">{value}</dd>\n                </div>\n              ))}\n            </dl>\n          </Section>\n        </Tabs.Content>\n      </Tabs.Root>\n    </article>\n  );\n}",
  "automation-builder": "/**\n * A rule editor wired to the farm's own vocabulary. It starts from the rule:\n *\n *   When soil moisture falls below 28% (and rain is not expected), open Zone 3 irrigation for 12 minutes.\n *\n * `AutomationBuilder` edits DATA. It validates with `validateAutomationRule`, shows problems inline,\n * and only calls `onSubmit` for a valid rule. Nothing evaluates the rule and nothing is sent: saving\n * here stores the rule in this component's state and says so.\n *\n * The rain forecast is application-provided demo data. KinetixUI fetches no forecast.\n */\nconst SUBJECTS: readonly KinetixBuilderSubject[] = [\n  { id: \"soil-moisture\", label: \"Soil moisture\", unit: \"%\" },\n  { id: \"rain-forecast\", label: \"Rain forecast\" },\n  { id: \"air-temperature\", label: \"Air temperature\", unit: \"°C\" },\n];\n\nconst TARGETS: readonly KinetixBuilderTarget[] = [\n  { id: \"zone-3\", label: \"Zone 3 irrigation\", commands: [{ id: \"open\", label: \"Open\" }, { id: \"close\", label: \"Close\" }] },\n  { id: \"zone-2\", label: \"Zone 2 irrigation\", commands: [{ id: \"open\", label: \"Open\" }, { id: \"close\", label: \"Close\" }] },\n  { id: \"pump-01\", label: \"Pump Station\", commands: [{ id: \"turn-on\", label: \"Turn on\" }, { id: \"turn-off\", label: \"Turn off\" }] },\n];\n\nconst BLANK: KinetixAutomationRule = { id: \"rule-new\", name: \"\", enabled: true, conditions: [], actions: [] };\nconst nameOf = (_kind: \"subject\" | \"scope\" | \"target\", id: string) =>\n  SUBJECTS.find((s) => s.id === id)?.label.toLowerCase() ?? TARGETS.find((t) => t.id === id)?.label;\n\nexport function AutomationBuilderExample() {\n  const [draft, setDraft] = React.useState<KinetixAutomationRule>(agritechRule);\n  const [saved, setSaved] = React.useState<KinetixAutomationRule | null>(null);\n\n  return (\n    <section aria-label=\"Automation builder\" className=\"flex flex-col gap-4\">\n      <SimNotice scenario={agritech} />\n\n      <div className=\"flex flex-wrap gap-2\">\n        <button type=\"button\" className={BUTTON} onClick={() => setDraft(BLANK)}>\n          Start from a blank rule\n        </button>\n        <button type=\"button\" className={BUTTON} onClick={() => setDraft(agritechRule)}>\n          Reset to the Zone 3 rule\n        </button>\n      </div>\n\n      <AutomationBuilder\n        value={draft}\n        onChange={setDraft}\n        subjects={SUBJECTS}\n        targets={TARGETS}\n        labelFor={nameOf}\n        submitLabel=\"Save as demo state\"\n        onSubmit={(rule) => setSaved(rule)}\n      />\n\n      {saved ? (\n        <div role=\"status\" className=\"flex flex-col gap-2 rounded-xl border border-border bg-card p-4\">\n          <p className=\"text-label-md font-medium text-foreground\">Saved as demo state — nothing is executed.</p>\n          <p className=\"text-label-sm text-muted-foreground\">\n            The rule is {saved.enabled ? \"enabled\" : \"disabled\"}: {summarizeAutomationRule(saved, { label: nameOf })}\n          </p>\n          <AutomationRuleView rule={saved} labelFor={nameOf} hideSummary />\n        </div>\n      ) : null}\n    </section>\n  );\n}",
  "pairing-flow": "/**\n * A nine-step pairing reference. The steps a person sees:\n *\n *   1 choose a method   2 searching   3 device found   4 identify   5 verify it is yours\n *   6 configure         7 choose a place   8 check it works   9 done\n *\n * The state machine is the package's, not this file's: `advancePairing` / `transitionPairing` decide\n * what may follow what, and this component only reports intent to it. \"Searching\" and \"found\" are two\n * screens inside the machine's one `discover` stage.\n *\n * NO Bluetooth, Wi-Fi or network scanning happens. Durations come from a fixture and run on a small\n * timer here. Under `prefers-reduced-motion` there are no timers: each simulated wait is finished by a\n * button instead, so nothing advances on its own.\n */\nconst UI_STEPS = [\"Choose a method\", \"Searching\", \"Device found\", \"Identify\", \"Verify it is yours\", \"Configure\", \"Choose a place\", \"Check it works\", \"Done\"] as const;\nconst PLACES = [\"Living room\", \"Hallway\", \"Kitchen\", \"Office\", \"Bedroom\", \"Zone 2\", \"Zone 3\", \"Utility yard\"];\nconst DEMO_CODE = \"KX2468\";\n/** Stages that begin with a simulated wait; the others begin by asking the person for something. */\nconst STARTS_WORKING: readonly KinetixPairingStage[] = [\"discover\", \"identify\", \"verify\"];\nconst durationOf = (stage: KinetixPairingStage) => pairingHappyPath.find((step) => step.stage === stage)?.durationMs ?? 1000;\n\nfunction uiStepOf(flow: KinetixPairingFlowState, working: boolean): number {\n  if (flow.status === \"idle\" || flow.status === \"cancelled\") return 0;\n  switch (flow.stage) {\n    case \"discover\":\n      return working || flow.status === \"failed\" ? 1 : 2;\n    case \"identify\":\n      return 3;\n    case \"authenticate\":\n      return 4;\n    case \"configure\":\n      return 5;\n    case \"assign\":\n      return 6;\n    case \"verify\":\n      return 7;\n    default:\n      return 8;\n  }\n}\n\nexport function PairingFlowExample() {\n  const reducedMotion = useReducedMotion();\n  const [flow, setFlow] = React.useState<KinetixPairingFlowState>(startPairingFlow);\n  // `visit` counts every flow change, so \"which wait am I in\" can never leak from an earlier visit to a stage.\n  const [visit, setVisit] = React.useState(0);\n  const [waiting, setWaiting] = React.useState<{ visit: number; working: boolean } | null>(null);\n  const [method, setMethod] = React.useState<KinetixPairingMethod>(\"bluetooth\");\n  const [scenarioId, setScenarioId] = React.useState(\"none\");\n  const [recovered, setRecovered] = React.useState(false);\n  const [foundId, setFoundId] = React.useState<string | null>(null);\n  const [code, setCode] = React.useState(\"\");\n  const [name, setName] = React.useState(\"\");\n  const [place, setPlace] = React.useState(PLACES[0]!);\n  const [note, setNote] = React.useState(\"\");\n  const headingRef = React.useRef<HTMLHeadingElement>(null);\n  const failureRef = React.useRef<HTMLDivElement>(null);\n  const mounted = React.useRef(false);\n\n  const scenario = pairingFailureScenarios.find((s) => s.id === scenarioId);\n  const found = pairingDevices[flow.method ?? method].find((d) => d.id === foundId) ?? pairingDevices[flow.method ?? method][0]!;\n  const acceptedCode = found.code ?? DEMO_CODE;\n  const codeLength = normalizePairingCode(acceptedCode).length;\n  const codeShapeOk = validatePairingCode(code, { length: codeLength });\n\n  const working = waiting?.visit === visit ? waiting.working : STARTS_WORKING.includes(flow.stage) && flow.status === \"active\";\n  const uiStep = uiStepOf(flow, working);\n  const started = flow.status !== \"idle\";\n\n  /** Every change to the flow goes through here, and always through the package's machine. */\n  const apply = (next: KinetixPairingFlowState) => {\n    setFlow(next);\n    setVisit((v) => v + 1);\n    setNote(\"\");\n  };\n  const send = (event: KinetixPairingEvent) => apply(advancePairing(flow, event));\n  const replayTo = (stage: KinetixPairingStage) => {\n    let state = advancePairing(startPairingFlow(), { type: \"start\", method: flow.method ?? method });\n    while (state.stage !== stage && state.status === \"active\") state = advancePairing(state, { type: \"next\" });\n    apply(state);\n  };\n  const setWorking = (value: boolean) => setWaiting({ visit, working: value });\n\n  /** A simulated wait has finished: the scripted failure strikes here, or the flow moves on. */\n  const workDone = () => {\n    if (flow.status !== \"active\") return;\n    const struck = scenario && !recovered && scenario.stage === flow.stage;\n    if (struck) return send({ type: \"fail\", code: scenario.code });\n    if (flow.stage === \"authenticate\" && normalizePairingCode(code) !== normalizePairingCode(acceptedCode)) {\n      return send({ type: \"fail\", code: \"authentication-failed\" });\n    }\n    if (flow.stage === \"discover\" || flow.stage === \"identify\") return setWorking(false);\n    send({ type: \"next\" });\n  };\n\n  React.useEffect(() => {\n    if (!working || flow.status !== \"active\" || reducedMotion) return;\n    const timer = setTimeout(workDone, durationOf(flow.stage));\n    return () => clearTimeout(timer);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [working, visit, reducedMotion]);\n\n  React.useEffect(() => {\n    if (!mounted.current) {\n      mounted.current = true;\n      return;\n    }\n    (flow.status === \"failed\" ? failureRef.current : headingRef.current)?.focus();\n  }, [uiStep, flow.status, visit]);\n\n  const recover = (kind: KinetixPairingRecoveryKind) => {\n    const strikes = !!scenario && scenario.stage === flow.stage;\n    if (kind === \"retry\") {\n      if (strikes) setRecovered(true);\n      setCode(\"\");\n      return send({ type: \"retry\" });\n    }\n    if (kind === \"back\") return send({ type: \"back\" });\n    if (kind === \"cancel\") return send({ type: \"cancel\" });\n    if (kind === \"reset\") {\n      setRecovered(true);\n      return replayTo(\"discover\");\n    }\n    if (kind === \"update\") {\n      setRecovered(true);\n      return replayTo(flow.stage);\n    }\n    setNote(kind === \"contact\" ? \"In a product this would open help. Nothing happens in this demo.\" : \"In a product this would open settings. Nothing happens in this demo.\");\n  };\n\n  const startOver = () => {\n    setFlow(startPairingFlow());\n    setVisit((v) => v + 1);\n    setRecovered(false);\n    setCode(\"\");\n    setNote(\"\");\n    setFoundId(null);\n  };\n\n  const pickScenario = (id: string) => {\n    setScenarioId(id);\n    setRecovered(false);\n    const next = pairingFailureScenarios.find((s) => s.id === id);\n    if (next) setMethod(next.method);\n  };\n  const backAllowed = transitionPairing(flow, { type: \"back\" }).ok;\n  const cancelAllowed = transitionPairing(flow, { type: \"cancel\" }).ok;\n\n  const heading = flow.status === \"cancelled\" ? \"Setup cancelled\" : `Step ${uiStep + 1} of ${UI_STEPS.length}: ${UI_STEPS[uiStep]}`;\n\n  return (\n    <section aria-label=\"Pairing flow\" className=\"flex max-w-3xl flex-col gap-4\">\n      <SimNotice text=\"Simulated — no Bluetooth, Wi-Fi or network scanning happens. Devices, codes and delays are scripted fixtures in your browser.\" />\n\n      <label className=\"flex flex-col gap-1 text-label-md text-foreground\">\n        Simulate a failure\n        <select\n          value={scenarioId}\n          disabled={started && flow.status !== \"cancelled\"}\n          onChange={(event) => pickScenario(event.target.value)}\n          className=\"min-h-11 rounded-md border border-input bg-background px-2 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-60\"\n        >\n          <option value=\"none\">None: pair successfully</option>\n          {pairingFailureScenarios.map((s) => (\n            <option key={s.id} value={s.id}>\n              {s.title} ({describePairingMethod(s.method)}, {s.code})\n            </option>\n          ))}\n        </select>\n        {scenario ? <span className=\"text-label-sm text-muted-foreground\">{scenario.recoveryOutcome}</span> : null}\n      </label>\n\n      <PairingStepper flow={flow} horizontal />\n\n      <div className=\"flex min-w-0 flex-col gap-4 rounded-2xl border border-border bg-card p-4\">\n        <h4 ref={headingRef} tabIndex={-1} className=\"text-title-sm text-foreground focus-visible:outline-none\">\n          {heading}\n        </h4>\n\n        {flow.status === \"failed\" ? (\n          <PairingFailure ref={failureRef} tabIndex={-1} code={flow.failure} onAction={(_id, action) => recover(action.kind)} className=\"focus-visible:outline-none\" />\n        ) : null}\n\n        {flow.status === \"cancelled\" ? (\n          <>\n            <p className=\"text-label-md text-muted-foreground\">Nothing was set up, and nothing was stored.</p>\n            <button type=\"button\" className={`${BUTTON} self-start`} onClick={startOver}>\n              Start again\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"idle\" ? (\n          <>\n            <PairingMethodPicker\n              value={method}\n              methods={KINETIX_PAIRING_METHODS}\n              onChange={(next) => {\n                setMethod(next);\n                if (scenario && scenario.method !== next) setScenarioId(\"none\");\n              }}\n            />\n            <button type=\"button\" className={`${BUTTON} self-start`} onClick={() => send({ type: \"start\", method })}>\n              Start setup\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && working ? (\n          <>\n            <p className=\"text-label-md text-muted-foreground\">\n              {pairingHappyPath.find((s) => s.stage === flow.stage)?.label}… (simulated, about {(durationOf(flow.stage) / 1000).toFixed(1)} s)\n            </p>\n            {reducedMotion ? (\n              <button type=\"button\" className={`${BUTTON} self-start`} onClick={workDone}>\n                Finish this step\n              </button>\n            ) : null}\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"discover\" ? (\n          <fieldset className=\"m-0 flex min-w-0 flex-col gap-2 border-0 p-0\">\n            <legend className=\"mb-1 text-label-md text-foreground\">\n              {pairingDevices[flow.method!].length} sample {pairingDevices[flow.method!].length === 1 ? \"device\" : \"devices\"} found (fixture data)\n            </legend>\n            {pairingDevices[flow.method!].map((device) => (\n              <label key={device.id} className=\"flex min-h-11 items-center gap-2 rounded-lg border border-border px-3 text-label-md text-foreground\">\n                <input type=\"radio\" name=\"found-device\" className=\"size-4\" checked={found.id === device.id} onChange={() => setFoundId(device.id)} />\n                <span className=\"min-w-0 break-words\">\n                  {device.name} <span className=\"text-muted-foreground\">· {device.hint}</span>\n                </span>\n              </label>\n            ))}\n            <button type=\"button\" className={`${BUTTON} self-start`} onClick={() => send({ type: \"next\" })}>\n              Continue with {found.name}\n            </button>\n          </fieldset>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"identify\" ? (\n          <>\n            <p className=\"text-label-md text-foreground\">\n              Does <strong className=\"font-medium\">{found.hint}</strong> match the label on your {found.name}?\n            </p>\n            <button type=\"button\" className={`${BUTTON} self-start`} onClick={() => send({ type: \"next\" })}>\n              Yes, that is my device\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"authenticate\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              if (codeShapeOk) setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-code\" className=\"text-label-md text-foreground\">\n              Setup code\n            </label>\n            <input\n              id=\"pairing-code\"\n              value={code}\n              onChange={(event) => setCode(event.target.value)}\n              autoComplete=\"off\"\n              spellCheck={false}\n              aria-describedby=\"pairing-code-hint\"\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-3 font-mono text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            />\n            <p id=\"pairing-code-hint\" className=\"text-label-sm text-muted-foreground\">\n              {codeLength} characters. Demo code: <span className=\"font-mono text-foreground\">{acceptedCode}</span>. The shape is checked here; only the device can say whether it is the right code.\n            </p>\n            <button type=\"submit\" disabled={!codeShapeOk} className={`${BUTTON} self-start`}>\n              Verify code\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"configure\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-name\" className=\"text-label-md text-foreground\">\n              Device name\n            </label>\n            <input\n              id=\"pairing-name\"\n              value={name || found.name}\n              onChange={(event) => setName(event.target.value)}\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-3 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            />\n            <button type=\"submit\" className={`${BUTTON} self-start`}>\n              Apply settings\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"assign\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-place\" className=\"text-label-md text-foreground\">\n              Room or zone\n            </label>\n            <select\n              id=\"pairing-place\"\n              value={place}\n              onChange={(event) => setPlace(event.target.value)}\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-2 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            >\n              {PLACES.map((p) => (\n                <option key={p}>{p}</option>\n              ))}\n            </select>\n            <button type=\"submit\" className={`${BUTTON} self-start`}>\n              Place it here\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"complete\" ? (\n          <>\n            <p className=\"text-label-md text-foreground\">\n              {name || found.name} is set up in {place}. It responded when checked.\n            </p>\n            <p className=\"text-label-sm text-muted-foreground\">Simulated: no device was paired, connected to or stored.</p>\n            <button type=\"button\" className={`${BUTTON} self-start`} onClick={startOver}>\n              Pair another device\n            </button>\n          </>\n        ) : null}\n\n        {note ? <p className=\"text-label-sm text-muted-foreground\">{note}</p> : null}\n      </div>\n\n      {started && flow.status !== \"complete\" && flow.status !== \"cancelled\" ? (\n        <div className=\"flex flex-wrap gap-2\">\n          <button type=\"button\" className={BUTTON} disabled={!backAllowed} onClick={() => send({ type: \"back\" })}>\n            Back\n          </button>\n          <button type=\"button\" className={BUTTON} disabled={!cancelAllowed} onClick={() => send({ type: \"cancel\" })}>\n            Cancel setup\n          </button>\n        </div>\n      ) : null}\n    </section>\n  );\n}",
  "telemetry-history": "/**\n * Telemetry over time: twelve kinds of reading in the states a real fleet is actually in, then two\n * trends with a threshold band, a gap where the sensor did not answer, and the data table that backs\n * the chart for anyone who cannot read a line.\n *\n * SIMULATED, fabricated data measured from one fixed instant. Nothing is sampled from a device.\n */\nconst NOW = AGRITECH_START;\nconst ago = (ms: number) => new Date(Date.parse(NOW) - ms).toISOString();\nconst MINUTE = 60_000;\nconst HOUR = 60 * MINUTE;\n\nconst RANGES = [\n  { id: \"6h\", label: \"Last 6 hours\", ms: 6 * HOUR },\n  { id: \"24h\", label: \"Last 24 hours\", ms: 24 * HOUR },\n  { id: \"7d\", label: \"Last 7 days\", ms: 7 * 24 * HOUR },\n] as const;\n\n/** Keep the points inside the window. A gap (`quality: \"missing\"`) survives the cut, so it still draws. */\nfunction within(series: KinetixTelemetrySeries | undefined, windowMs: number): KinetixTelemetrySeries {\n  const from = Date.parse(NOW) - windowMs;\n  return { deviceId: series?.deviceId ?? \"\", metric: series?.metric ?? \"\", points: (series?.points ?? []).filter((p) => Date.parse(String(p.timestamp)) >= from) };\n}\n\nexport function TelemetryHistoryExample() {\n  const [range, setRange] = React.useState<(typeof RANGES)[number][\"id\"]>(\"7d\");\n  const windowMs = RANGES.find((r) => r.id === range)!.ms;\n  const find = (deviceId: string, metric: string) => agritech.series.find((s) => s.deviceId === deviceId && s.metric === metric);\n\n  return (\n    <section aria-label=\"Telemetry history\" className=\"flex flex-col gap-6\">\n      <SimNotice text=\"Simulated — fabricated readings measured from a fixed instant. Nothing is sampled from a device.\" />\n\n      <Section title=\"Readings now\" hint=\"Normal, warning, critical, stale and unavailable are different states, never one confident number.\">\n        <TelemetryGrid label=\"Readings by kind\">\n          <TelemetryMetric metric=\"temperature\" value={24.6} timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric metric=\"humidity\" value={88} thresholds={{ warningHigh: 80, criticalHigh: 95 }} timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric metric=\"soil-moisture\" value={34} thresholds={{ warningLow: 28 }} timestamp={ago(40_000)} now={NOW} />\n          <TelemetryMetric metric=\"pressure\" value={null} quality=\"missing\" timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric metric=\"air-quality\" value={212} timestamp={ago(10_000)} now={NOW} />\n          <TelemetryMetric metric=\"motion\" value={2} unit=\"events\" timestamp={ago(15_000)} now={NOW} />\n          <TelemetryMetric metric=\"light-level\" value={420} timestamp={ago(30_000)} now={NOW} />\n          <TelemetryMetric metric=\"flow\" value={18} thresholds={{ warningLow: 20 }} timestamp={ago(10_000)} now={NOW} />\n          <TelemetryMetric metric=\"water-level\" value={6} thresholds={{ warningLow: 20, criticalLow: 10 }} timestamp={ago(45_000)} now={NOW} />\n          <TelemetryMetric metric=\"power\" value={1820} timestamp={ago(5_000)} now={NOW} />\n          <TelemetryMetric metric=\"battery\" value={18} timestamp={ago(60_000)} now={NOW} />\n          <TelemetryMetric metric=\"signal-strength\" value={61} timestamp={ago(2 * HOUR)} staleAfterMs={15 * MINUTE} now={NOW} />\n        </TelemetryGrid>\n      </Section>\n\n      <Section title=\"History\" hint=\"The band is the product-set threshold. A break in the line is a reading that was due and did not arrive.\">\n        <div role=\"radiogroup\" aria-label=\"Time range\" className=\"flex flex-wrap gap-2\">\n          {RANGES.map((r) => (\n            <button\n              key={r.id}\n              type=\"button\"\n              role=\"radio\"\n              aria-checked={range === r.id}\n              onClick={() => setRange(r.id)}\n              className=\"inline-flex min-h-9 items-center rounded-md border border-input px-3 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring aria-checked:border-primary aria-checked:bg-primary aria-checked:text-primary-foreground\"\n            >\n              {r.label}\n            </button>\n          ))}\n        </div>\n        <TelemetryTrend\n          series={within(find(\"soil-04\", \"soil-moisture\"), windowMs)}\n          label=\"Soil moisture, Zone 3\"\n          thresholds={{ warningLow: 28 }}\n          height={140}\n          now={NOW}\n          dataTable\n        />\n        <TelemetryTrend\n          series={within(find(\"weather-01\", \"temperature\"), Math.min(windowMs, 24 * HOUR))}\n          label=\"Weather station temperature, with a gap\"\n          height={120}\n          now={NOW}\n          dataTable\n        />\n      </Section>\n    </section>\n  );\n}",
  "alert-center": "/**\n * An alert centre over Site 04: fleet health above, the alert list below, and an acknowledge flow.\n *\n * Acknowledged is not resolved. Acknowledging says \"I have seen this\"; the alert stays in the list and\n * the device keeps counting against health until the condition itself clears. Use the button to make\n * another sensor stop answering and watch the counts and the list change together.\n *\n * SIMULATED: nothing is sent to a device, and acknowledging changes only this component's state.\n */\nexport function AlertCenterExample() {\n  const iot = useIotSimulation(operations, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [showAcknowledged, setShowAcknowledged] = React.useState(true);\n  const silent = !sim.devices[\"s-101\"]!.reachable;\n  const alerts = selectAlerts(sim, { includeAcknowledged: showAcknowledged });\n\n  return (\n    <section aria-label=\"Alert centre\" className=\"flex flex-col gap-6\">\n      <SimNotice scenario={operations}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <Section title=\"Site 04 health\">\n        <DeviceHealthSummary summary={selectFleetHealth(sim)} noun={{ one: \"device\", other: \"devices\" }} />\n      </Section>\n\n      <Section title=\"Alerts\">\n        <div className=\"flex flex-wrap items-center gap-3\">\n          <label className=\"flex min-h-9 cursor-pointer items-center gap-2 text-label-sm text-foreground\">\n            <input type=\"checkbox\" className=\"size-4\" checked={showAcknowledged} onChange={(event) => setShowAcknowledged(event.target.checked)} />\n            Show acknowledged\n          </label>\n          <button type=\"button\" className={BUTTON} onClick={() => iot.setReachable(\"s-101\", silent)}>\n            {silent ? \"Vessel sensor S-101 answers again\" : \"Make Vessel sensor S-101 stop answering\"}\n          </button>\n        </div>\n        <AlertList\n          alerts={alerts}\n          deviceName={(id) => deviceOf(sim, id).name}\n          onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n          now={sim.now}\n          emptyLabel=\"Nothing to show.\"\n        />\n      </Section>\n    </section>\n  );\n}",
  "device-fleet": "export function DeviceFleetExample() {\n  // Worst first. The ordering comes from KINETIX_DEVICE_STATUSES via compareDeviceAttention, so the\n  // list and the badges agree about which state is worse instead of holding two opinions.\n  const devices = [...DEMO_DEVICES].sort(compareDeviceAttention);\n\n  return (\n    <section className=\"flex flex-col gap-4\">\n      <header className=\"flex flex-wrap items-baseline justify-between gap-3\">\n        <h3 className=\"text-title-sm text-foreground\">Cold chain · Site 4</h3>\n        <DeviceStateSummary devices={devices} />\n      </header>\n\n      <div className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,17rem),1fr))] gap-3\">\n        {devices.map((device) => (\n          <DeviceCard\n            key={device.id}\n            device={device}\n            reading={DEMO_READINGS[device.id]}\n            now={DEMO_NOW}\n          />\n        ))}\n      </div>\n    </section>\n  );\n}",
  "telemetry-board": "export function TelemetryBoardExample() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        {/* This sensor stopped answering four hours ago. The card shows that rather than a last-known\n            value dressed up as current, and its plot stops where the readings stopped. */}\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </div>\n\n      {/* The trend on its own, at the size a detail view would give it. The two dropouts in the load\n          series are breaks in the line and a count in the footer — never interpolated across. */}\n      <figure className=\"flex flex-col gap-2 rounded-xl border border-border bg-card p-4\">\n        <figcaption className=\"text-label-sm uppercase tracking-wide text-muted-foreground\">\n          Load · last 3 hours\n        </figcaption>\n        <TelemetryTrend series={DEMO_SERIES.load} precision={1} height={120} />\n      </figure>\n    </div>\n  );\n}",
  "connection-troubleshooting": "/**\n * Six devices that a single \"offline\" dot would describe identically, and the facts that tell them\n * apart. The library does not diagnose the cause — it has no transport and cannot know whether a\n * gateway died or a firewall changed — it separates the signals so a person can.\n */\nconst CASES: { device: KinetixDevice; what: string }[] = [\n  { device: deviceById(\"probe-a\"), what: \"Reporting on schedule. Nothing to do.\" },\n  { device: deviceById(\"probe-b\"), what: \"Reachable, but the data behind it is hours old — the case a status field alone gets wrong.\" },\n  { device: deviceById(\"air-1\"), what: \"Weak signal and a fault reported by the device itself.\" },\n  { device: deviceById(\"probe-c\"), what: \"Not heard from in days, and the battery was nearly flat when it was.\" },\n  { device: { ...deviceById(\"gateway-1\"), signal: undefined }, what: \"No signal figure reported. Not the same as a signal of zero.\" },\n  { device: deviceById(\"meter-1\"), what: \"Mid-update. Its last reading is not its current reading.\" },\n];\n\nexport function ConnectionTroubleshootingExample() {\n  return (\n    <div className=\"grid gap-3 md:grid-cols-2\">\n      {CASES.map(({ device, what }) => (\n        <div key={device.id} className=\"flex flex-col gap-3 rounded-xl border border-border bg-card p-4\">\n          <div className=\"flex items-start justify-between gap-3\">\n            <span className=\"text-label-md text-foreground\">{device.name}</span>\n            <DeviceStatusBadge status={device.status} />\n          </div>\n          <ConnectionHealth device={device} freshnessMs={10 * 60_000} now={DEMO_NOW} />\n          <p className=\"text-label-sm text-muted-foreground\">{what}</p>\n        </div>\n      ))}\n    </div>\n  );\n}",
  "alert-inbox": "export function AlertInboxExample() {\n  // Local demo state. Acknowledging here changes this component and nothing else — there is no\n  // request, no device, and no server. See the note on the page.\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  const [showAcknowledged, setShowAcknowledged] = React.useState(false);\n\n  const alerts = DEMO_ALERTS.map((alert) =>\n    acknowledged[alert.id] ? { ...alert, acknowledgedAt: acknowledged[alert.id] } : alert,\n  );\n\n  // `activeAlerts` sorts newest first and, by default, leaves acknowledged ones out — so \"show\n  // acknowledged\" is a flag it already takes rather than a second code path here.\n  const visible = activeAlerts(alerts, { includeAcknowledged: showAcknowledged });\n  const loudest = highestAlertSeverity(alerts);\n\n  return (\n    <section className=\"flex flex-col gap-3\">\n      <header className=\"flex flex-wrap items-center justify-between gap-3\">\n        <p className=\"text-label-md text-foreground\">\n          {visible.length} alert{visible.length === 1 ? \"\" : \"s\"}\n          {loudest ? <span className=\"text-muted-foreground\"> · loudest is {loudest}</span> : null}\n        </p>\n        <label className=\"flex min-h-6 cursor-pointer items-center gap-2 py-1 text-label-sm text-muted-foreground\">\n          <input\n            type=\"checkbox\"\n            checked={showAcknowledged}\n            onChange={(event) => setShowAcknowledged(event.target.checked)}\n            className=\"size-4 rounded border-input\"\n          />\n          Show acknowledged\n        </label>\n      </header>\n\n      {visible.length === 0 ? (\n        <p className=\"rounded-lg border border-dashed border-border p-6 text-center text-label-md text-muted-foreground\">\n          Nothing unacknowledged.\n        </p>\n      ) : (\n        <ul className=\"flex flex-col gap-2\">\n          {visible.map((alert) => (\n            <li key={alert.id}>\n              <AlertCard\n                alert={alert}\n                deviceName={deviceById(alert.deviceId).name}\n                now={DEMO_NOW}\n                action={\n                  alert.acknowledgedAt ? null : (\n                    <button\n                      type=\"button\"\n                      onClick={() => setAcknowledged((prev) => ({ ...prev, [alert.id]: DEMO_NOW }))}\n                      className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                    >\n                      {/* Named, not an icon: \"Acknowledge\" beside a device name is what a screen\n                          reader announces, and a bare tick is not. */}\n                      <span className=\"sr-only\">Acknowledge alert: {alert.message}. </span>\n                      Acknowledge\n                    </button>\n                  )\n                }\n              />\n            </li>\n          ))}\n        </ul>\n      )}\n    </section>\n  );\n}",
  "device-dashboard": "/**\n * Everything below is LOCAL DEMO STATE.\n *\n * Toggling a device, moving a slider or acknowledging an alert changes a `useState` value in this\n * component and nothing else. `@kinetixui/iot` has no transport — no MQTT, no BLE, no WebSocket, no\n * HTTP client — so nothing here reaches a device, and a showcase that implied otherwise would be\n * advertising a capability the package does not have.\n */\nconst GROUPS = [\"All\", \"Cold store A\", \"Plant room\", \"Bay 2\"] as const;\ntype Group = (typeof GROUPS)[number];\n\n// The product supplies these. `@kinetixui/iot` hard-codes no mode vocabulary, because the same\n// control serves a chiller, an irrigation valve and a conveyor.\nconst MODES = [\n  { id: \"cool\", label: \"Cool\" },\n  { id: \"hold\", label: \"Hold\" },\n  { id: \"defrost\", label: \"Defrost\", description: \"Unavailable until the cycle completes\", unavailable: true },\n];\n\nexport function DeviceDashboardExample() {\n  const [group, setGroup] = React.useState<Group>(\"All\");\n  const [selectedId, setSelectedId] = React.useState<string>(\"probe-a\");\n  const [overrides, setOverrides] = React.useState<Record<string, KinetixDeviceStatus>>({});\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  // Confirmed values — what the imaginary device has reported.\n  const [powered, setPowered] = React.useState<\"on\" | \"off\">(\"on\");\n  const [intensity, setIntensity] = React.useState(62);\n  const [target, setTarget] = React.useState(4);\n  const [mode, setMode] = React.useState(\"cool\");\n\n  // Requested values — what the user has asked for and the device has not confirmed yet.\n  const [pending, setPending] = React.useState<null | { kind: \"power\" | \"level\" | \"target\" | \"mode\"; value: string | number }>(null);\n\n  // A command that resolves after a beat, so the requested-versus-confirmed gap is visible rather\n  // than theoretical. A product would replace this with whatever its transport reports back.\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPowered(pending.value as \"on\" | \"off\");\n      if (pending.kind === \"level\") setIntensity(pending.value as number);\n      if (pending.kind === \"target\") setTarget(pending.value as number);\n      if (pending.kind === \"mode\") setMode(pending.value as string);\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const request = (kind: \"power\" | \"level\" | \"target\" | \"mode\", value: string | number) => setPending({ kind, value });\n\n  const devices: KinetixDevice[] = DEMO_DEVICES.map((device) =>\n    overrides[device.id] ? { ...device, status: overrides[device.id]! } : device,\n  );\n  const inGroup = group === \"All\" ? devices : devices.filter((device) => device.locationName === group);\n  const ordered = [...inGroup].sort(compareDeviceAttention);\n  const summary = summarizeDevices(inGroup);\n  const selected = deviceById(selectedId);\n\n  // One resolution for all four controls, so they cannot disagree about whether the device is\n  // reachable or a command is outstanding.\n  const control = resolveControlState({\n    deviceStatus: selected.status,\n    commandStatus: pending ? \"sent\" : undefined,\n  });\n  const alerts = DEMO_ALERTS.map((a) => (acknowledged[a.id] ? { ...a, acknowledgedAt: acknowledged[a.id] } : a));\n  const openAlerts = alerts.filter((a) => !a.acknowledgedAt);\n\n  return (\n    <div className=\"flex flex-col gap-4\">\n      {/* ---------------------------------------------------------------- header */}\n      <header className=\"flex flex-col gap-3 rounded-xl border border-border bg-card p-4\">\n        <div className=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-2\">\n          <h3 className=\"text-title-sm text-foreground\">Cold chain · Site 4</h3>\n          {/* A count, not a verdict. Whether two offline devices is fine depends on what they are. */}\n          <p className=\"text-label-sm text-muted-foreground\">\n            {summary.total} device{summary.total === 1 ? \"\" : \"s\"} · {summary.needsAttention} needing attention ·{\" \"}\n            {openAlerts.length} open alert{openAlerts.length === 1 ? \"\" : \"s\"}\n          </p>\n        </div>\n\n        {/* The group selector every product surveyed puts here, generalised from \"rooms\". */}\n        <div role=\"tablist\" aria-label=\"Device group\" className=\"-mx-1 flex gap-1 overflow-x-auto px-1 pb-1\">\n          {GROUPS.map((name) => (\n            <button\n              key={name}\n              role=\"tab\"\n              type=\"button\"\n              aria-selected={group === name}\n              onClick={() => setGroup(name)}\n              className={[\n                \"shrink-0 rounded-full px-3 py-1.5 text-label-sm transition-colors duration-200 motion-reduce:transition-none\",\n                \"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\",\n                group === name ? \"bg-foreground text-background\" : \"border border-input text-muted-foreground hover:text-foreground\",\n              ].join(\" \")}\n            >\n              {name}\n            </button>\n          ))}\n        </div>\n\n        <DeviceStateSummary devices={inGroup} />\n      </header>\n\n      {/* ---------------------------------------------------------------- fleet + detail */}\n      <div className=\"grid gap-4 xl:grid-cols-[minmax(0,1fr)_20rem]\">\n        <section aria-label=\"Devices\" className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,16rem),1fr))] gap-3\">\n          {ordered.map((device) => {\n            const isSelected = device.id === selectedId;\n            return (\n              <DeviceCard\n                key={device.id}\n                device={device}\n                reading={DEMO_READINGS[device.id]}\n                now={DEMO_NOW}\n                className={isSelected ? \"border-foreground/40 ring-1 ring-foreground/20\" : \"\"}\n                action={\n                  <button\n                    type=\"button\"\n                    onClick={() => setSelectedId(device.id)}\n                    aria-pressed={isSelected}\n                    className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                  >\n                    <span className=\"sr-only\">Show details for {device.name}. </span>\n                    Details\n                  </button>\n                }\n              />\n            );\n          })}\n          {ordered.length === 0 ? (\n            <p className=\"rounded-xl border border-dashed border-border p-6 text-label-md text-muted-foreground\">\n              No devices in this group.\n            </p>\n          ) : null}\n        </section>\n\n        {/* The detail panel: the tile-to-detail pattern, as a column beside the grid on wide screens\n            and a section below it on narrow ones. */}\n        <aside aria-label={`Detail: ${selected.name}`} className=\"flex flex-col gap-4 rounded-xl border border-border bg-card p-4\">\n          <div className=\"flex flex-col gap-1\">\n            <span className=\"text-label-sm uppercase tracking-wide text-muted-foreground\">Selected device</span>\n            <span className=\"text-title-sm text-foreground\">{selected.name}</span>\n            <span className=\"text-label-sm text-muted-foreground\">{selected.locationName}</span>\n          </div>\n\n          {/* The control layer, wired to LOCAL DEMO STATE.\n              A request is held for 1.1s before it \"confirms\", because that is what a device on a\n              real network does — and because the state worth showing is the one in between. Nothing\n              here reaches a device: `@kinetixui/iot` has no transport of any kind. */}\n          {/* `min-w-0` because a <fieldset> defaults to `min-inline-size: min-content` and will not shrink\n              below its widest child — which put a 370px panel inside a 320px column. */}\n          <fieldset className=\"flex min-w-0 flex-col gap-4 border-t border-border pt-4\">\n            <legend className=\"sr-only\">Demonstration controls for {selected.name}</legend>\n\n            <DevicePowerControl\n              state={powered}\n              requested={pending?.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined}\n              control={control}\n              label={`${selected.name} power`}\n              onToggle={(next) => request(\"power\", next)}\n            />\n\n            <DeviceLevelControl\n              value={intensity}\n              target={pending?.kind === \"level\" ? (pending.value as number) : undefined}\n              control={control}\n              label=\"Intensity\"\n              unit=\"%\"\n              onCommit={(next) => request(\"level\", next)}\n            />\n\n            <DeviceSetpointControl\n              current={selected.id === \"probe-a\" ? 4.2 : undefined}\n              target={target}\n              requestedTarget={pending?.kind === \"target\" ? (pending.value as number) : undefined}\n              min={-20}\n              max={25}\n              unit=\"°C\"\n              label=\"Target temperature\"\n              control={control}\n              onCommit={(next) => request(\"target\", next)}\n            />\n\n            <DeviceModeControl\n              modes={MODES}\n              value={mode}\n              requested={pending?.kind === \"mode\" ? (pending.value as string) : undefined}\n              control={control}\n              label=\"Operating mode\"\n              onSelect={(id) => request(\"mode\", id)}\n            />\n\n            <div className=\"flex flex-col gap-1.5\">\n              <span className=\"text-label-md text-foreground\">Simulate a state</span>\n              <div className=\"flex flex-wrap gap-1.5\">\n                {([\"online\", \"syncing\", \"stale\", \"offline\", \"error\"] as const).map((status) => (\n                  <button\n                    key={status}\n                    type=\"button\"\n                    onClick={() => setOverrides((prev) => ({ ...prev, [selected.id]: status }))}\n                    className=\"rounded-full border border-input px-2.5 py-1 text-label-sm text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none\"\n                  >\n                    {describeDeviceStatus(status)}\n                  </button>\n                ))}\n              </div>\n              {/* One polite live region for the whole panel, announced only when the reader acted.\n                  Telemetry updates are deliberately NOT announced — a dashboard that narrates every\n                  reading is a dashboard nobody can use with a screen reader. */}\n              <p aria-live=\"polite\" className=\"text-label-sm text-muted-foreground\">\n                {overrides[selected.id] ? `${selected.name} is now ${describeDeviceStatus(overrides[selected.id]!).toLowerCase()}.` : \"\"}\n              </p>\n            </div>\n          </fieldset>\n        </aside>\n      </div>\n\n      {/* ---------------------------------------------------------------- telemetry */}\n      <section aria-label=\"Telemetry\" className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,14rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </section>\n\n      {/* ---------------------------------------------------------------- alerts + activity */}\n      <div className=\"grid gap-4 lg:grid-cols-2\">\n        <section aria-label=\"Alerts\" className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-wide text-muted-foreground\">Alerts</h4>\n          {openAlerts.length === 0 ? (\n            <p className=\"rounded-lg border border-dashed border-border p-4 text-label-md text-muted-foreground\">\n              Nothing unacknowledged.\n            </p>\n          ) : (\n            <ul className=\"flex flex-col gap-2\">\n              {openAlerts.map((alert) => (\n                <li key={alert.id}>\n                  <AlertCard\n                    alert={alert}\n                    deviceName={deviceById(alert.deviceId).name}\n                    now={DEMO_NOW}\n                    action={\n                      <button\n                        type=\"button\"\n                        onClick={() => setAcknowledged((prev) => ({ ...prev, [alert.id]: DEMO_NOW }))}\n                        className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                      >\n                        <span className=\"sr-only\">Acknowledge alert: {alert.message}. </span>\n                        Acknowledge\n                      </button>\n                    }\n                  />\n                </li>\n              ))}\n            </ul>\n          )}\n        </section>\n\n        <section aria-label=\"Activity\" className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-wide text-muted-foreground\">Recent commands</h4>\n          {/* The time-rail activity list: the timestamp gutter is the structure, not a trailing note. */}\n          <ul className=\"flex flex-col\">\n            {DEMO_COMMANDS.map((command) => (\n              <li key={command.id} className=\"grid grid-cols-[auto_1fr] gap-3 border-s border-border ps-4 pb-4 last:pb-0\">\n                <span aria-hidden=\"true\" className=\"-ms-5 mt-1.5 size-2 rounded-full bg-border\" />\n                <span className=\"flex flex-col gap-0.5\">\n                  <span className=\"text-label-md text-foreground\">{deviceById(command.deviceId).name}</span>\n                  <CommandStatus command={command} showName now={DEMO_NOW} />\n                </span>\n              </li>\n            ))}\n          </ul>\n        </section>\n      </div>\n    </div>\n  );\n}",
  "connected-space": "/**\n * A connected space: zones, the devices in one of them, and the automations that run it.\n *\n * Everything below is LOCAL DEMO STATE, and every device, zone and routine here is invented.\n * Toggling something changes a `useState` value in this component. `@kinetixui/iot` has no transport\n * — no MQTT, no BLE, no Matter, no WebSocket — so nothing reaches a device, and a showcase implying\n * otherwise would be advertising a capability the package does not have.\n *\n * The one behaviour worth watching: a command is held for 1.1s before it confirms. During that\n * window the control shows what you **asked for** as clearly distinct from what the device has\n * **reported**, which is the gap most device UIs paper over with an optimistic update.\n */\nconst NOW = \"2026-01-01T12:00:00.000Z\";\nconst ago = (ms: number) => new Date(Date.parse(NOW) - ms).toISOString();\nconst ahead = (ms: number) => new Date(Date.parse(NOW) + ms).toISOString();\n\nconst ZONES = [\n  { id: \"hall\", name: \"Packing hall\", kind: \"Zone\", deviceCount: 12, activeCount: 7, category: \"light\" as const, summary: \"21°C · 48% RH\" },\n  { id: \"field\", name: \"North field\", kind: \"Zone\", deviceCount: 8, activeCount: 4, attentionCount: 1, category: \"pump\" as const, summary: \"3 of 8 valves open\" },\n  { id: \"store\", name: \"Cold store\", kind: \"Site\", deviceCount: 5, activeCount: 0, category: \"sensor\" as const, summary: \"All within range\" },\n];\n\nconst FIXTURES: KinetixDevice[] = [\n  { id: \"bench\", name: \"Bench lamps\", type: \"light\", status: \"online\", lastSeenAt: ago(30_000), locationName: \"Packing hall\" },\n  { id: \"bay\", name: \"Loading bay flood\", type: \"light\", status: \"online\", lastSeenAt: ago(90_000), locationName: \"Packing hall\" },\n  { id: \"yard\", name: \"Yard flood\", type: \"light\", status: \"offline\", lastSeenAt: ago(3 * 3_600_000), locationName: \"Packing hall\" },\n];\n\nconst ROUTINES: KinetixAutomation[] = [\n  {\n    id: \"shutdown\",\n    name: \"End of shift\",\n    kind: \"scene\",\n    status: \"idle\",\n    enabled: true,\n    actions: \"9 lights off, 2 doors locked\",\n    lastRunAt: ago(14 * 3_600_000),\n  },\n  {\n    id: \"irrigation\",\n    name: \"Evening irrigation\",\n    kind: \"schedule\",\n    status: \"idle\",\n    enabled: true,\n    trigger: \"Weekdays 18:30\",\n    actions: \"2 valves, 40 min\",\n    lastRunAt: ago(20 * 3_600_000),\n    nextRunAt: ahead(6 * 3_600_000),\n  },\n  {\n    id: \"frost\",\n    name: \"Frost protection\",\n    kind: \"routine\",\n    status: \"failed\",\n    enabled: true,\n    trigger: \"Outside below 2°C\",\n    actions: \"Circulation pump\",\n    lastRunAt: ago(90 * 60_000),\n    errorMessage: \"Pump did not acknowledge\",\n  },\n];\n\ntype Pending = { id: string; kind: \"power\" | \"level\"; value: string | number };\n\nexport function ConnectedSpaceExample() {\n  const [zoneId, setZoneId] = React.useState(\"hall\");\n  const [power, setPower] = React.useState<Record<string, \"on\" | \"off\">>({ bench: \"on\", bay: \"off\", yard: \"on\" });\n  const [level, setLevel] = React.useState<Record<string, number>>({ bench: 100, bay: 40, yard: 70 });\n  const [pending, setPending] = React.useState<Pending | null>(null);\n  const [routines, setRoutines] = React.useState(ROUTINES);\n  const [openId, setOpenId] = React.useState<string | null>(\"bench\");\n\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPower((p) => ({ ...p, [pending.id]: pending.value as \"on\" | \"off\" }));\n      if (pending.kind === \"level\") setLevel((l) => ({ ...l, [pending.id]: pending.value as number }));\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const controlFor = (device: KinetixDevice) =>\n    resolveControlState({\n      deviceStatus: device.status,\n      commandStatus: pending?.id === device.id ? \"sent\" : undefined,\n    });\n\n  const zone = ZONES.find((z) => z.id === zoneId) ?? ZONES[0]!;\n\n  return (\n    <section aria-label=\"Connected space\" className=\"flex flex-col gap-6\">\n      {/* ------------------------------------------------------------------ zones */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-wide text-muted-foreground\">Zones</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n          {ZONES.map((z) => (\n            <DeviceGroupCard\n              key={z.id}\n              name={z.name}\n              kind={z.kind}\n              deviceCount={z.deviceCount}\n              activeCount={z.activeCount}\n              attentionCount={z.attentionCount}\n              category={z.category}\n              summary={z.summary}\n              onSelect={() => setZoneId(z.id)}\n              className={z.id === zoneId ? \"ring-2 ring-ring ring-offset-2 ring-offset-background\" : undefined}\n            />\n          ))}\n        </div>\n      </div>\n\n      {/* ------------------------------------------------------------- the devices */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-wide text-muted-foreground\">{zone.name} — fixtures</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-3\">\n          {FIXTURES.map((device) => {\n            const control = controlFor(device);\n            const requestedPower = pending?.id === device.id && pending.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined;\n            const on = power[device.id] === \"on\";\n\n            return (\n              <DeviceControlCard\n                key={device.id}\n                device={device}\n                active={on && device.status === \"online\"}\n                control={control}\n                open={openId === device.id}\n                onOpenChange={(next) => setOpenId(next ? device.id : null)}\n                statusLine={\n                  device.status === \"offline\"\n                    ? \"Last reachable 3h ago\"\n                    : requestedPower\n                      ? `Turning ${requestedPower}`\n                      : on\n                        ? `${level[device.id]}% brightness`\n                        : \"Off\"\n                }\n                primaryControl={\n                  <DevicePowerControl\n                    state={power[device.id]}\n                    requested={requestedPower}\n                    control={control}\n                    label={`${device.name} power`}\n                    showLabel={false}\n                    onToggle={(next) => setPending({ id: device.id, kind: \"power\", value: next })}\n                  />\n                }\n                expanded={\n                  <DeviceLevelControl\n                    value={level[device.id]}\n                    target={pending?.id === device.id && pending.kind === \"level\" ? (pending.value as number) : undefined}\n                    control={control}\n                    label={`${device.name} brightness`}\n                    unit=\"%\"\n                    onCommit={(next) => setPending({ id: device.id, kind: \"level\", value: next })}\n                  />\n                }\n              />\n            );\n          })}\n        </div>\n      </div>\n\n      {/* ---------------------------------------------------------------- routines */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-wide text-muted-foreground\">Automations</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {routines.map((automation) => (\n            <RoutineCard\n              key={automation.id}\n              automation={automation}\n              now={NOW}\n              onToggleEnabled={(next) =>\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, enabled: next } : r)))\n              }\n              onRun={() => {\n                // A run that finishes on its own, so \"running\" is a state you can actually watch.\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, status: \"running\" } : r)));\n                setTimeout(\n                  () =>\n                    setRoutines((rs) =>\n                      rs.map((r) => (r.id === automation.id ? { ...r, status: \"idle\", lastRunAt: NOW } : r)),\n                    ),\n                  1800,\n                );\n              }}\n            />\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}"
};
